<div class="accessibility-dock" aria-label="Pengaturan aksesibilitas">
    <button class="accessibility-toggle" type="button" aria-expanded="false" aria-controls="accessibility-panel"><span aria-hidden="true">Aa</span><span class="sr-only">Buka pengaturan aksesibilitas</span></button>
    <section class="accessibility-panel" id="accessibility-panel" hidden aria-label="Pengaturan tampilan dan pembacaan">
        <div class="panel-heading"><strong>Aksesibilitas</strong><button type="button" class="icon-button" data-accessibility-close aria-label="Tutup pengaturan">×</button></div>
        <div class="accessibility-actions">
            <button type="button" data-text-step="-1">A− <span>Perkecil teks</span></button><button type="button" data-text-step="1">A+ <span>Perbesar teks</span></button><button type="button" data-text-reset>Atur ulang teks</button>
            <button type="button" data-accessibility="contrast">Kontras tinggi</button><button type="button" data-accessibility="grayscale">Skala abu-abu</button><button type="button" data-accessibility="underline">Garis bawah tautan</button><button type="button" data-accessibility="focus">Sorot fokus</button><button type="button" data-accessibility="motion">Kurangi animasi</button>
            <button type="button" data-theme="light">Mode terang</button><button type="button" data-theme="dark">Mode gelap</button><button type="button" data-accessibility-reset>Reset semua</button>
        </div>
        <p class="small-note">Pengaturan disimpan pada perangkat dan dapat direset kapan saja.</p>
    </section>
</div>
<div class="reading-bar" data-reading-bar hidden>
    <div class="reading-title"><strong>Baca halaman</strong><span data-reading-status role="status">Siap dibacakan</span></div>
    <div class="reading-controls"><button type="button" data-speech-action="play">Putar</button><button type="button" data-speech-action="pause">Jeda</button><button type="button" data-speech-action="resume">Lanjutkan</button><button type="button" data-speech-action="stop">Hentikan</button><label>Kecepatan<select data-speech-rate><option value="0.8">Lambat</option><option value="1" selected>Normal</option><option value="1.2">Cepat</option></select></label><label>Suara<select data-speech-voice><option value="">Otomatis</option></select></label></div>
</div>
